# Lesson 1, part 3 (who reads the statements and what each reader asks) and part 4 (who requires reporting: law, standards, regulator, audit).
# Israeli facts: corporate tax 23% (since 2018); Companies Law 1999; Securities Law 1968 and the 1970 periodic and immediate reports regulations
# (annual report within three months, quarterly within two months); Israeli Accounting Standard No. 29 (IFRS for public companies from 1.1.2008).

# ================================================================ part 3
opener(3, 'מי קורא את הדוחות', 'שאלת החלק: מי קורא את הדוחות של קפה נועה, ומה כל אחד מחפש בהם?',
       ['משתמשים חיצוניים ומשתמשים פנימיים', 'כל קורא והשאלה שלו', 'הבנק, הספק ורשות המסים, כל אחד בגיליון', 'פערי מידע ובעיית הנציג: למה צריך כללים'], 35)

S('s-extint', 'קוראים מבחוץ ומבפנים', 'שני סוגי קוראים',
  '<div class="row eq2 top">'
  + DEF('משתמשים חיצוניים (External users)', 'מי שקורא מבחוץ, ולא רואה מה קורה בתוך העסק. הדוחות הכספיים הם מקור המידע העיקרי שלו.', 'הבנק, הספקים, המשקיעים, רשות המסים.', n=1, trm='extu')
  + DEF('משתמשים פנימיים (Internal users)', 'המנהלים של העסק, שיכולים לבקש כל מספר שהם רוצים.', 'נועה מבקשת דוח מכירות לפי שעה ביום.', n=2, trm='intu') + '</div>'
  + BAND('dg', 'החשבונאות הפיננסית נכתבת בשביל הקוראים מבחוץ. הם לא יכולים לבקש דוח מיוחד, ולכן הדוח הכללי חייב לענות להם.', 3)
  + TOON('bank', 'אני לא יכול להיכנס למטבח. יש לי רק את הדוחות.', 4), kick='חלק 3 · הגדרה והדגמה')

U = [('משקיעים', 'כמה ירוויחו על הכסף?', 'investor', 1, 0), ('בנק ומלווים', 'האם יחזירו את ההלוואה?', 'bank', 2, 0), ('ספקים', 'האם ישלמו לי בזמן?', 'truck', 3, 0),
     ('רשות המסים', 'כמה מס מגיע?', 'taxman', 4, 0), ('עובדים', 'האם העבודה יציבה?', 'worker', 5, 0), ('הנהלה', 'איך לנהל טוב יותר?', 'cup', 6, 1)]
S('s-users', 'מי קורא את הדוחות', 'מי קורא את הדוחות של קפה נועה?',
  (('<div class="card hubw">' + HUB(U) + '</div>') if MODE == 'deck' else TABLE(['קורא', 'השאלה שלו'], [(a, b) for a, b, *_ in U]))
  , kick='חלק 3 · מפה')

S('s-users-q', 'כל קורא והשאלה שלו', 'כל קורא שואל שאלה אחרת',
  TABLE(['הקורא', 'ההחלטה שלו', 'מה הוא מחפש בדוחות'], [
      ['משקיע', 'לקנות מניות, להחזיק או למכור', 'רווח, צמיחה, דיבידנדים'],
      ['בנק ומלווים', 'לתת הלוואה, באיזה סכום ובאיזו ריבית', 'רווח שמכסה את התשלומים, חובות קיימים, נכסים לביטחון'],
      ['ספק', 'למכור באשראי, ולכמה ימים', 'מזומן וחובות לזמן קצר'],
      ['רשות המסים', 'כמה מס לגבות', 'הרווח, כבסיס לחישוב המס'],
      ['עובדים ואיגודים', 'להישאר, לדרוש שכר או בונוס', 'רווחיות ויציבות'],
      ['לקוחות', 'לחתום על חוזה ארוך', 'האם החברה תמשיך להתקיים'],
      ['אנליסטים והציבור', 'להמליץ, לסקר, להשוות', 'השוואה לחברות אחרות ולשנים קודמות']], cls='tight')
  + BAND('dg', 'אותו דוח משרת את כולם. לכן הוא נקרא ״דוח כללי״, ולכן הכללים שלו אחידים.', 1), kick='חלק 3 · הכלל')

SORTER('a-users', 'מי שואל', 'מי שואל את השאלה?', 'לכל שאלה, בחרו את הקורא שהכי סביר ששואל אותה.', ['משקיע', 'בנק', 'ספק', 'רשות המסים', 'עובדים'], [
    ('האם הרווח של קפה נועה מספיק כדי לשלם 14,000 ש״ח בשנה להחזר הלוואה?', 1, 'החלטת אשראי ארוכה: הבנק.'),
    ('אם אקנה 20% מהמניות ב-150,000 ש״ח, כמה ארוויח בשנה?', 0, 'החלטה לקנות מניות: משקיע.'),
    ('האם יש לבית הקפה מספיק מזומן כדי לשלם לי בעוד 60 יום על הפולים?', 2, 'אשראי קצר על סחורה: ספק.'),
    ('מה הרווח החייב במס של החברה בשנת 2026?', 3, 'חישוב המס: רשות המסים.'),
    ('האם החברה מרוויחה מספיק כדי לשלם בונוס בסוף השנה?', 4, 'שכר ובונוס: עובדים.')])

_d = {'A1': 'רווח שנתי לפי הדוחות', 'A2': 'החזר שנתי של ההלוואה', 'A3': 'הכיסוי המינימלי שהבנק דורש', 'A5': 'פי כמה הרווח מכסה את ההחזר', 'A6': 'עודף הכיסוי מעל הדרישה',
      'B1': 120000, 'B2': 14000, 'B3': 2}
QX('x-bank', 'שאלה 5', 'הבנק שוקל הלוואה',
   ['קפה נועה מבקשת מהבנק הלוואה, שההחזר השנתי שלה 14,000 ש״ח. לפי הדוחות, הרווח השנתי של בית הקפה 120,000 ש״ח. הבנק מאשר הלוואה רק אם הרווח השנתי גדול לפחות פי 2 מההחזר השנתי.',
    '<b>נדרש:</b> פי כמה הרווח מכסה את ההחזר, ובכמה הכיסוי עובר את הדרישה של הבנק?'],
   'הזינו את הנתונים. B5: הכיסוי. B6: הכיסוי פחות הדרישה.',
   _d, {'B5': '=B1/B2', 'B6': '=B5-B3'}, [240, 110], [], fmt={'B1': 'num0', 'B2': 'num0', 'B3': 'num0', 'B5': 'num2', 'B6': 'num2'},
   hints=['פי כמה: מחלקים את הרווח בהחזר, =B1/B2.', 'עודף הכיסוי: =B5-B3. מספר חיובי אומר שהדרישה מתקיימת.'], remind='=B1/B2', partial=['B5'],
   traps={'B5': [('=B2/B1', 'חילקתם הפוך. השאלה ״פי כמה הרווח גדול מההחזר״: הרווח במונה, =B1/B2.')]},
   steps=[dict(cells={'B5': '=B1/B2'}, note='כיסוי: =B1/B2, הרווח גדול פי 8.57 מההחזר.'), dict(cells={'B6': '=B5-B3'}, note='=B5-B3: עודף של 6.57 מעל הדרישה. הבנק יאשר.')],
   note=[('note', 'כך נראה יחס פיננסי: שני מספרים מהדוחות, אחד חלקי השני. במפגש 3 נלמד יחסים רבים כאלה.', 1)],
   done='כיסוי של פי 8.57, עודף של 6.57 מעל הדרישה. ההלוואה מאושרת.', xtitle='שאלה 5: הבנק')

_d = {'A1': 'מזומן בקופה ובבנק', 'A2': 'כסף צפוי מלקוחות ב-60 הימים הקרובים', 'A3': 'תשלומים שחייבים לשלם ב-60 הימים הקרובים', 'A4': 'האשראי שהספק שוקל לתת', 'A6': 'מה יישאר אחרי כל התשלומים', 'A7': 'המרווח מעל האשראי המבוקש',
      'B1': 25000, 'B2': 8000, 'B3': 21000, 'B4': 6000}
QX('x-supplier', 'שאלה 6', 'הספק שוקל אשראי',
   ['ספק הפולים שוקל לתת לקפה נועה אשראי של 6,000 ש״ח ל-60 יום. הוא בודק בדוחות: יש לבית הקפה מזומן של 25,000 ש״ח, הוא צפוי לגבות מלקוחות 8,000 ש״ח ב-60 הימים הקרובים, והוא חייב לשלם באותה תקופה 21,000 ש״ח על שכר דירה ושכר עובדים.',
    '<b>נדרש:</b> כמה כסף יישאר לבית הקפה אחרי התשלומים, והאם זה מכסה את האשראי המבוקש?'],
   'הזינו את הנתונים. B6: מה יישאר. B7: המרווח מעל האשראי.',
   _d, {'B6': '=B1+B2-B3', 'B7': '=B6-B4'}, [300, 100], [], fmt={a: 'num0' for a in ['B1', 'B2', 'B3', 'B4', 'B6', 'B7']},
   hints=['מה שיש, ועוד מה שייכנס, פחות מה שיוצא: =B1+B2-B3.', 'המרווח: =B6-B4. חיובי: הספק מכוסה.'], remind='=B1+B2-B3', partial=['B6'],
   traps={'B6': [('=B1-B3', 'שכחתם את הכסף שצפוי להיכנס מלקוחות: =B1+B2-B3.')]},
   steps=[dict(cells={'B6': '=B1+B2-B3'}, note='=B1+B2-B3: יישארו 12,000 ש״ח.'), dict(cells={'B7': '=B6-B4'}, note='=B6-B4: מרווח של 6,000 ש״ח. הספק יכול לתת את האשראי.')],
   note=[('note', 'הספק מסתכל על הטווח הקצר: מזומן וחובות לחודשיים. הבנק בשאלה 5 הסתכל על רווח של שנים. שאלה אחרת, מספרים אחרים מאותם דוחות.', 1)],
   done='יישארו 12,000 ש״ח, מרווח של 6,000 מעל האשראי.', xtitle='שאלה 6: הספק')

S('s-tax', 'מס חברות', 'רשות המסים: גם היא קוראת את הדוח',
  DEF('מס חברות (Corporate tax)', 'מס שחברה משלמת למדינה מהרווח שלה. בישראל השיעור 23% מאז 2018.', 'חברה עם רווח לפני מס של 100,000 ש״ח: ' + XL('=100000*23%') + ' נותן מס של 23,000.', n=1, trm='ctax')
  + BAND('note', 'הרווח לצורכי מס נקבע לפי פקודת מס הכנסה, והוא יכול להיות שונה מהרווח בדוחות. בקורס נניח שהם שווים.', 2)
  + TOON('taxman', 'אני לא משקיע. אבל גם אני מקבל חלק מהרווח.', 3), kick='חלק 3 · הגדרה והדגמה')

_d = {'A1': 'רווח לפני מס', 'A2': 'שיעור מס חברות', 'A4': 'המס', 'A5': 'רווח אחרי מס', 'A6': 'החלק של יוסי (20%) ברווח אחרי מס', 'A7': 'שיעור ההחזקה של יוסי', 'B1': 120000, 'B2': 0.23, 'B7': 0.2}
QX('x-tax', 'שאלה 7', 'כמה מס תשלם קפה נועה?',
   ['הרווח לפני מס של קפה נועה בע״מ בשנת 2026 הוא 120,000 ש״ח. שיעור מס החברות 23%. יוסי מחזיק 20% מהמניות.',
    '<b>נדרש:</b> כמה מס תשלם החברה, מה הרווח אחרי מס, ומה החלק של יוסי ברווח אחרי מס?'],
   'הזינו את הנתונים, כולל 20% בתא B7. B4: המס. B5: הרווח אחרי מס. B6: החלק של יוסי.',
   _d, {'B4': '=B1*B2', 'B5': '=B1-B4', 'B6': '=B5*B7'}, [260, 110], [], fmt={'B1': 'num0', 'B2': 'pct0', 'B4': 'num0', 'B5': 'num0', 'B6': 'num0', 'B7': 'pct0'},
   hints=['המס: =B1*B2.', 'אחרי מס: =B1-B4. החלק של יוסי: =B5*B7.'], remind='=B1*B2', partial=['B4'],
   traps={'B6': [('=B1*B7', 'חישבתם מהרווח לפני מס. ליוסי מגיע חלק מהרווח <b>אחרי</b> מס: =B5*B7.')]},
   steps=[dict(cells={'B4': '=B1*B2'}, note='המס: =B1*B2, 27,600.'), dict(cells={'B5': '=B1-B4'}, note='אחרי מס: =B1-B4, 92,400.'), dict(cells={'B6': '=B5*B7'}, note='יוסי: =B5*B7, 18,480 ש״ח, ולא 24,000 כמו בשאלה 2.')],
   note=[('dg', 'בשאלה 2 יוסי חישב 24,000 ש״ח, כי שכח את המס. ההחלטה שלו עדיין טובה, אבל המספר היה גבוה מדי ב-5,520 ש״ח.', 1)],
   done='מס 27,600, רווח אחרי מס 92,400, ליוסי 18,480 ש״ח.', xtitle='שאלה 7: מס חברות')

S('s-asym', 'פערי מידע ובעיית הנציג', 'למה לא לסמוך פשוט על המנהל?',
  '<div class="row eq2 top">'
  + DEF('פערי מידע (Information asymmetry)', 'צד אחד יודע יותר מהצד השני. ההנהלה יודעת על העסק הרבה יותר מהקוראים בחוץ.', 'נועה יודעת שמכונת האספרסו עומדת להתקלקל. יוסי, המשקיע, לא יודע.', n=1, trm='asym')
  + DEF('בעיית הנציג (Agency problem)', 'המנהל אמור לעבוד בשביל הבעלים, אבל לפעמים דואג קודם לעצמו, והבעלים לא רואים כל מה שהוא עושה.', 'מנהל שמקבל בונוס לפי הרווח מעדיף שהרווח ייראה גבוה, גם כשהוא לא.', n=2, trm='agency') + '</div>'
  + BAND('dg', 'מכאן הצורך בשלושה דברים: כללים אחידים שקובעים איך מודדים, חובה לפרסם, ובודק חיצוני. זה חלק 4.', 3)
  + MEME('שני דוחות, אותו בית קפה', [('happy', 'הדוח שהמנהל היה רוצה לפרסם'), ('mag', 'הדוח שהמשקיע צריך לקבל')], 4, 'sm side'), kick='חלק 3 · הגדרה והדגמה')

_d = {'A1': 'הרווח האמיתי של השנה', 'A2': 'חשבון חשמל שהמנהל ״דחה״ לשנה הבאה', 'A3': 'שיעור הבונוס מהרווח המדווח', 'A5': 'הרווח המדווח', 'A6': 'הבונוס לפי הרווח האמיתי', 'A7': 'הבונוס לפי הרווח המדווח', 'A8': 'הבונוס הנוסף למנהל',
      'B1': 120000, 'B2': 4000, 'B3': 0.05}
MCX('m-3', 'בדיקה 3: הבונוס של המנהל', 'בדיקה 3: חשבון החשמל שנעלם',
    mc('m3', 'מנהל בית קפה מקבל בונוס של 5% מהרווח המדווח. הרווח האמיתי של השנה 120,000 ש״ח, אבל המנהל לא רשם חשבון חשמל של דצמבר, 4,000 ש״ח, ״כי ישולם בינואר״. מה הבעיה?', ['ייצוג לא נאמן שנובע מבעיית הנציג: הרווח מנופח, והמנהל מרוויח מזה', 'אין בעיה: על בסיס מזומן החשמל שייך לינואר', 'בעיה של עדכניות בלבד: הדוח יתפרסם מאוחר', 'בעיה של השוואתיות בלבד: בית קפה אחר רושם חשמל אחרת'], 0,
       'על בסיס מצטבר החשמל של דצמבר הוא הוצאה של דצמבר. בגיליון: הרווח המדווח גבוה ב-4,000, והבונוס גבוה ב-200 ש״ח. המנהל הרוויח מהטעות, וזו בדיוק בעיית הנציג.'),
    'הזינו את הנתונים. B5: הרווח המדווח. B6 ו-B7: הבונוס בשתי הגרסאות. B8: ההפרש.',
    _d, {'B5': '=B1+B2', 'B6': '=B1*B3', 'B7': '=B5*B3', 'B8': '=B7-B6'}, [290, 100], [], fmt={'B1': 'num0', 'B2': 'num0', 'B3': 'pct0', 'B5': 'num0', 'B6': 'num0', 'B7': 'num0', 'B8': 'num0'},
    hints=['הוצאה שלא נרשמה מגדילה את הרווח: =B1+B2.', 'בונוס: רווח כפול 5%. ההפרש: =B7-B6.'], remind='=B5*B3', partial=['B5'], xtitle='בדיקה 3: בונוס ורווח מדווח')

# ================================================================ part 4
opener(4, 'מי מחייב לדווח', 'שאלת החלק: מי קובע שחברה חייבת לפרסם דוחות, ולפי אילו כללים?',
       ['כללי חשבונאות מקובלים ותקני חשבונאות', 'התקינה הבינלאומית, האמריקאית והישראלית', 'החוקים בישראל: חוק החברות וחוק ניירות ערך', 'רשות ניירות ערך, דוחות תקופתיים ומאי״ה', 'ביקורת ורואה חשבון מבקר', 'מה מחקר מצא על איכות הדיווח'], 35)

S('s-gaap', 'כללים משותפים', 'שפה צריכה דקדוק: כללים משותפים',
  '<div class="card qstem"><p>' + TX('בשאלה 3 נועה ודן מדדו רווח בשתי דרכים, וההשוואה הטעתה ב-60,000 ש״ח. תארו לעצמכם אלפי חברות, שכל אחת מודדת בדרך שלה.') + '</p></div>'
  + '<div class="row eq2 top">'
  + DEF('כללי חשבונאות מקובלים (GAAP)', 'באנגלית Generally Accepted Accounting Principles: כל הכללים שלפיהם מכינים דוחות כספיים במדינה מסוימת.', 'בארצות הברית US GAAP. בישראל: תקינה ישראלית לחברות פרטיות, ותקינה בינלאומית לחברות ציבוריות.', n=1, trm='gaap')
  + DEF('תקן חשבונאות (Accounting standard)', 'כלל כתוב שאומר איך לטפל בסוג מסוים של עסקה.', 'תקן הכנסות קובע שהמינוי של חדר הכושר נרשם כהכנסה לאורך 12 חודשים.', n=2, trm='std') + '</div>'
  + TOON('gavel', 'בלי כללים משותפים, כל חברה ממציאה את הרווח שלה.', 3), kick='חלק 4 · הגדרה והדגמה')

S('s-ifrs', 'מי כותב את הכללים', 'מי כותב את הכללים?',
  '<div class="row eq2 top"><div class="col">'
  + DEF('המוסד הבינלאומי לתקינה בחשבונאות (IASB)', 'באנגלית International Accounting Standards Board. גוף עצמאי בלונדון שכותב את כללי הדיווח הבינלאומיים ואת המסגרת המושגית.', 'הוא פרסם את התקן שקובע איך חברה רושמת חוזה שכירות ארוך.', n=1, trm='iasb')
  + DEF('תקני דיווח כספי בינלאומיים (IFRS)', 'באנגלית International Financial Reporting Standards: הכללים שה-IASB כותב. יותר מ-140 מדינות ותחומי שיפוט מחייבים אותם.', 'חברה ישראלית וחברה גרמנית מדווחות לפי IFRS, ולכן אפשר להשוות ביניהן.', n=2, trm='ifrs') + '</div><div class="col">'
  + DEF('הוועדה האמריקאית לתקינה בחשבונאות (FASB)', 'באנגלית Financial Accounting Standards Board: הגוף שכותב את US GAAP, כללי החשבונאות בארצות הברית.', 'חברה אמריקאית שנסחרת בניו יורק מדווחת לפי US GAAP.', n=3, trm='fasb')
  + DEF('המוסד הישראלי לתקינה בחשבונאות', 'באנגלית Israel Accounting Standards Board. כותב את התקנים הישראליים. תקן מספר 29 שלו חייב חברות ציבוריות לעבור ל-IFRS מ-1.1.2008.', 'קפה נועה, חברה פרטית, רשאית לדווח לפי התקינה הישראלית.', n=4, trm='isasb') + '</div></div>', kick='חלק 4 · הגדרה והדגמה')

