QX('x-q4', 'שאלה 8', 'איפה הרבעון הרביעי?',
   ['חברת המזון ״שחר מזון בע״מ״ (חברה שהומצאה להמחשה) היא תאגיד מדווח. במאי״ה מצאתם: רווח נקי של 260 מיליון ש״ח ברבעון 1, 310 ברבעון 2 ו-280 ברבעון 3. בדוח השנתי: רווח נקי של 1,200 מיליון ש״ח לשנה כולה. דוח נפרד לרבעון 4 אין, כי הוא חלק מהדוח השנתי.',
    '<b>נדרש:</b> מה הרווח הנקי של רבעון 4, ובכמה הוא גבוה מהרווח של רבעון 3?'],
   'הזינו את הנתונים במיליוני ש״ח. B5: רבעון 4. B8: ההפרש מול רבעון 3.',
   _d, {'B5': '=B6-SUM(B2:B4)', 'B8': '=B5-B4'}, [200, 110], [1], fmt={a: 'num0' for a in ['B2', 'B3', 'B4', 'B5', 'B6', 'B8']},
   hints=['השנה כולה היא סכום ארבעת הרבעונים. לכן רבעון 4 הוא השנה פחות שלושת הראשונים: =B6-SUM(B2:B4).'], remind='=B6-SUM(B2:B4)', partial=['B5'],
   traps={'B5': [('=B6/4', 'זה ממוצע רבעוני, לא רבעון 4. מורידים מהשנה את שלושת הרבעונים הידועים.')]},
   steps=[dict(cells={'B5': '=B6-SUM(B2:B4)'}, note='רבעון 4: =B6-SUM(B2:B4), כלומר 350 מיליון.'), dict(cells={'B8': '=B5-B4'}, note='מול רבעון 3: =B5-B4, עלייה של 70 מיליון.')],
   note=[('note', 'אנליסטים עושים את זה בכל שנה, כי רבעון 4 לא מתפרסם בנפרד. זה גם תרגיל ראשון בקריאת דוחות ממאי״ה.', 1)],
   done='רבעון 4: 350 מיליון ש״ח, עלייה של 70 מיליון מול רבעון 3.', xtitle='שאלה 8: הרבעון הרביעי')

S('s-audit', 'ביקורת', 'מי בודק את הדוחות?',
  '<div class="row eq3 top">'
  + DEF('ביקורת (Audit)', 'בדיקה חיצונית של הדוחות, כדי שאפשר יהיה לסמוך עליהם. היא נותנת ביטחון סביר, לא ערובה.', 'סופרים מלאי, מקבלים אישור יתרה מהבנק, ובודקים מדגם של חשבוניות.', n=1, trm='audit')
  + DEF('רואה חשבון מבקר (Auditor)', 'רואה חשבון בעל רישיון, שאינו עובד בחברה ואינו תלוי בה, ושבודק את הדוחות.', 'משרד רואי חשבון חיצוני שבודק את קפה נועה פעם בשנה.', n=2, trm='auditor')
  + DEF('חוות דעת (Audit opinion)', 'המסקנה הכתובה של המבקר. ״נקייה״: הדוחות משקפים באופן נאות, מכל הבחינות המהותיות.', 'הסתייגות או אזהרה בחוות הדעת היא סימן לקורא לבדוק לעומק.', n=3, trm='opinion') + '</div>'
  + BAND('dg', 'הביקורת מחזקת שני מאפיינים שלמדנו: [[verif|ניתנות לאימות]] ו[[faith|ייצוג נאמן]]. היא עונה על [[asym|פערי המידע]] מחלק 3.', 4)
  + TOON('mag', 'אני לא בודק כל קבלה. אני בודק מספיק כדי לחתום.', 5), kick='חלק 4 · הגדרה והדגמה')

